class Solution:
    def totalSteps(self, nums):
        st = []
        ans = 0
        for x in nums:
            t = 0
            while st and st[-1][0] <= x:
                t = max(t, st.pop()[1])
            if st:
                t += 1
            ans = max(ans, t)
            st.append((x, t))
        return ans

