class Solution {
public:
    int totalSteps(vector<int>& nums) {
        vector<pair<int,int>> st;
        int ans = 0;
        for (int x : nums) {
            int t = 0;
            while (!st.empty() && st.back().first <= x) {
                t = max(t, st.back().second);
                st.pop_back();
            }
            if (!st.empty()) t++;
            ans = max(ans, t);
            st.push_back({x, t});
        }
        return ans;
    }
};

