class Solution {
    public int totalSteps(int[] nums) {
        Deque<int[]> st = new ArrayDeque<>();
        int ans = 0;
        for (int x : nums) {
            int t = 0;
            while (!st.isEmpty() && st.peek()[0] <= x) {
                t = Math.max(t, st.pop()[1]);
            }
            if (!st.isEmpty()) t++;
            ans = Math.max(ans, t);
            st.push(new int[]{x, t});
        }
        return ans;
    }
}

